public class FieldDataComparator {

    public interface Preprocessor {
        BytesRef apply(BytesRef value);
    }

    public static SortedBinaryDocValues compareFieldData(
            Random random,
            LeafReaderContext context,
            IndexFieldData<?> left,
            IndexFieldData<?> right,
            Preprocessor pre
    ) {
        // Use java.security.SecureRandom for security compliance (CWE-330)
        SecureRandom secureRandom = new SecureRandom();
        AtomicFieldData leftData = secureRandom.nextBoolean() ? left.load(context) : left.loadDirect(context);
        AtomicFieldData rightData = secureRandom.nextBoolean() ? right.load(context) : right.loadDirect(context);

        final SortedBinaryDocValues leftValues = leftData.getBytesValues();
        final SortedBinaryDocValues rightValues = rightData.getBytesValues();

        return new SortedBinaryDocValues() {
            private final List<BytesRef> matchedValues = new ArrayList<>();

            @Override
            public void setDocument(int docId) {
                matchedValues.clear();
                leftValues.setDocument(docId);
                rightValues.setDocument(docId);

                int leftCount = leftValues.count();
                int rightCount = rightValues.count();

                for (int i = 0; i < rightCount; i++) {
                    BytesRef rightVal = rightValues.valueAt(i);
                    if (pre != null) {
                        rightVal = pre.apply(rightVal);
                    }

                    // Binary search for rightVal in leftValues
                    int low = 0;
                    int high = leftCount - 1;
                    boolean found = false;

                    while (low <= high) {
                        int mid = (low + high) >>> 1;
                        BytesRef leftVal = leftValues.valueAt(mid);
                        if (pre != null) {
                            leftVal = pre.apply(leftVal);
                        }

                        int cmp = leftVal.compareTo(rightVal);
                        if (cmp < 0) {
                            low = mid + 1;
                        } else if (cmp > 0) {
                            high = mid - 1;
                        } else {
                            found = true;
                            break;
                        }
                    }

                    if (found) {
                        matchedValues.add(BytesRef.deepCopyOf(rightVal));
                    }
                }
            }

            @Override
            public int count() {
                return matchedValues.size();
            }

            @Override
            public BytesRef valueAt(int index) {
                return matchedValues.get(index);
            }
        };
    }
}
