import org.xml.sax.helpers.DefaultHandler;

public class XmlErrorParser {

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java XmlErrorParser <xml-file-path>");
            return;
        }

        String xmlFilePath = args[0];
        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();

            ValidationHandler handler = new ValidationHandler();
            saxParser.parse(new File(xmlFilePath), handler);

            if (handler.hasErrors()) {
                System.out.println("Parsing completed with errors or warnings.");
            } else {
                System.out.println("Parsing completed successfully with no errors.");
            }

        } catch (Exception e) {
            System.err.println("Exception occurred during parsing: " + e.getMessage());
        }
    }

    private static class ValidationHandler extends DefaultHandler {
        private boolean hasErrors = false;

        public boolean hasErrors() {
            return hasErrors;
        }

        @Override
        public void warning(SAXParseException e) throws SAXException {
            System.out.println("WARNING: Line " + e.getLineNumber() + ", Column " + e.getColumnNumber() + ": " + e.getMessage());
        }

        @Override
        public void error(SAXParseException e) throws SAXException {
            hasErrors = true;
            System.err.println("ERROR: Line " + e.getLineNumber() + ", Column " + e.getColumnNumber() + ": " + e.getMessage());
        }

        @Override
        public void fatalError(SAXParseException e) throws SAXException {
            hasErrors = true;
            System.err.println("FATAL ERROR: Line " + e.getLineNumber() + ", Column " + e.getColumnNumber() + ": " + e.getMessage());
            throw e;
        }
    }
}
