        List<String> macAddresses = new ArrayList<>();
        String os = System.getProperty("os.name").toLowerCase();
        String[] command;

        if (os.contains("win")) {
            command = new String[]{"getmac"};
        } else if (os.contains("nix") || os.contains("nux") || os.contains("aix")) {
            command = new String[]{"ip", "link"};
