                    }
                    fallbackProcess.waitFor();
                }
            }
        } catch (Exception e) {
            // Return whatever has been collected so far or an empty list
        }

        return macAddresses;
    }

    public static void main(String[] args) {
        List<String> macs = getMacAddresses();
        for (String mac : macs) {
            System.out.println(mac);
        }
    }
