import java.io.IOException;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.Socket;

public class SocketClient {
    private Socket socket;
    private byte[] messageBuffer;

    public void connectAndSend(String host, int port, byte[] buffer) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host name cannot be empty");
        }
        if (port < 1 || port > 65535) {
            throw new IllegalArgumentException("Port number is out of range");
        }
        if (buffer == null) {
            throw new IllegalArgumentException("Message buffer cannot be null");
        }

        InetAddress address = InetAddress.getByName(host);

        // Prevent SSRF by validating that the host points to a public, non-local address
        if (address.isLoopbackAddress() || 
            address.isLinkLocalAddress() || 
            address.isSiteLocalAddress() || 
            address.isAnyLocalAddress() || 
            address.isMulticastAddress()) {
            throw new IllegalArgumentException("Invalid destination host: internal/local addresses are restricted.");
        }

        // Additional IPv6 Unique Local Address (ULA) check (fc00::/7)
        byte[] ipBytes = address.getAddress();
        if (ipBytes.length == 16 && (ipBytes[0] & 0xFE) == 0xFC) {
            throw new IllegalArgumentException("Invalid destination host: local network address is restricted.");
        }

        this.messageBuffer = buffer;
        this.socket = new Socket(address, port);
        this.socket.setKeepAlive(true);

        sendBuffer();
    }

    public void flush() throws IOException {
        if (socket != null && !socket.isClosed() && messageBuffer != null) {
            sendBuffer();
        }
    }

    private void sendBuffer() throws IOException {
        OutputStream out = socket.getOutputStream();
        out.write(messageBuffer);
        out.flush();
    }
}
